private String unescapeId(String input) throws IllegalArgumentException, StringIndexOutOfBoundsException {
    // Check that the input string is not null or empty
    if (input == null || input.isEmpty()) {
        throw new IllegalArgumentException("Input string cannot be null or empty");
    }

    // Create a character buffer for the output string
    StringBuilder output = new StringBuilder();

    // Loop through each character in the input string
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);

        // Check if the character is a backslash
        if (c == '\\') {
            // Read the next character to determine the escape code
            i++;
            if (i >= input.length()) {
                throw new StringIndexOutOfBoundsException("Incomplete escape sequence");
            }
            char esc = input.charAt(i);

            // Handle the escape sequences
            switch (esc) {
                case 'n':
                    output.append('\n');
                    break;
                case 't':
                    output.append('\t');
                    break;
                case 'r':
                    output.append('\r');
                    break;
                case '"':
                    output.append('"');
                    break;
                case '\b':
                    output.append('\b');
                    break;
                case '\\':
                    output.append('\\');
                    break;
                default:
                    throw new IllegalArgumentException("Unsupported escape sequence: \\" + esc);
            }
        } else {
            // Append the character as is
            output.append(c);
        }
    }

    // Return the unescaped output
    return output.toString();
}

