private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    byte[] encoded = new byte[2];
    bb.get(encoded);
    int inputValue = ((encoded[0] & 0xFF) << 8) | (encoded[1] & 0xFF);

    if (inputValue < 0x80) { // ASCII character
        sb.append((char) inputValue);
        return i + 1;
    } else if (inputValue >= 0xC0 && inputValue < 0xD8) { // starting of a multi-byte UTF-8 character
        encoded = new byte[4];
        bb.get(encoded, 2, 2);

        int codePoint = (encoded[1] & 0xFF) << 8 | (encoded[0] & 0xFF);
        for (int k = 3; k > 0; k--) {
            int b = bb.get();
            codePoint = (codePoint << 8) | b;
        }

        switch (codePoint >> 18) {
            case 0: // 1-byte character
                sb.append((char) ( codePoint & 0x7F));
                return i + 3;
