private void addReverse(final InputStream[] files){
    List<InputStream> reversedFiles = Arrays.asList(files); // Convert to list to easily reverse
    for (int i = reversedFiles.size() - 1; i >= 0; i--) { // Loop in reverse order
        try {
            byte[] data = new byte[1024]; // Buffer for reading file data
            int bytesRead;
            while ((bytesRead = reversedFiles.get(i).read(data)) != -1) {
                System.out.write(data, 0, bytesRead);
            } // Read and print each file
        } catch (IOException e) {
            System.err.println("Error reading file: " + e.getMessage());
        } finally {
            try {
                reversedFiles.get(i).close(); // Close the file to free resources
            } catch (IOException e) {
                System.err.println("Error closing file: " + e.getMessage());
            }
        }
    }
}

