    }
    if (index + len > str.length()) {
        throw new IllegalArgumentException("Index and length combination creates invalid span");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        if ((str.charAt(i) & 0x80) != 0) {
            size++; // 1 byte for most chars
            if ((str.charAt(i) & 0xC0) != 0x80) {
